/** Events */
export const events = {
	askpassClosed: makeEvent<AskpassClosedEvent>("askpass_closed"),
	askpassPrompt: makeEvent<AskpassPromptEvent>("askpass_prompt"),
	commitGraphWritten: makeEvent<CommitGraphWrittenEvent>("commit_graph_written"),
	gitStatus: makeEvent<GitStatusEvent>("git_status"),
	jobEnded: makeEvent<JobEndedEvent>("job_ended"),
	jobProgress: makeEvent<JobProgressEvent>("job_progress"),
	repoRefsChanged: makeEvent<RepoRefsChangedEvent>("repo_refs_changed"),
	repoSummary: makeEvent<RepoSummaryEvent>("repo_summary"),
	watchWarning: makeEvent<WatchWarningEvent>("watch_warning"),
	workspaceAddReport: makeEvent<WorkspaceAddReportEvent>("workspace_add_report"),
	workspaceChanged: makeEvent<WorkspaceChangedEvent>("workspace_changed"),
};

/* Types */
/**  What an add job did. */
export type AddReport = {
	workspace_id: WorkspaceId,
	job_id: JobId,
	/**  New in the workspace, in path order. */
	added: RepoView[],
	/**  Found, and already in the workspace (GRP-1). */
	already_present: RepoView[],
	/**  Folders that were not added or could not be read. */
	refused: Refusal[],
};

/**  What the running build is and where it runs. */
export type AppInfo = {
	name: string,
	version: string,
	/**  `std::env::consts::OS`, e.g. `linux`, `windows`, `macos`. */
	os: string,
	/**  `std::env::consts::ARCH`, e.g. `x86_64`, `aarch64`. */
	arch: string,
	/**
	 *  The desktop's UI font family, when the platform tells it (GTK on
	 *  Linux). The UI puts it before its own list of system fonts (UI-26).
	 */
	ui_font: string | null,
	/**
	 *  The desktop's monospace font family, when the platform tells it
	 *  (GNOME's settings on Linux). The UI puts it before its own list of
	 *  monospace fonts (UI-26).
	 */
	code_font: string | null,
};

/**
 *  Code themes and fonts (UI-24, UI-26). Saved as top-level keys of the
 *  file.
 */
export type Appearance = {
	/**  Used while the app theme resolves to light. */
	code_theme_light: CodeTheme,
	/**  Used while the app theme resolves to dark. */
	code_theme_dark: CodeTheme,
	/**  A font family name; `None` is the system UI font. */
	ui_font: string | null,
	/**  In CSS pixels, [`MIN_FONT_SIZE`] to [`MAX_FONT_SIZE`]. */
	ui_font_size: number,
	/**  A font family name; `None` is the system monospace font. */
	code_font: string | null,
	/**  In CSS pixels, [`MIN_FONT_SIZE`] to [`MAX_FONT_SIZE`]. */
	code_font_size: number,
};

/**
 *  A prompt was withdrawn before it was answered, as when its job ended,
 *  sent as event `askpass_closed`.
 */
export type AskpassClosedEvent = {
	prompt_id: number,
};

/**  A prompt as the dialog shows it, naming the repo and the job. */
export type AskpassPrompt = {
	prompt_id: number,
	kind: PromptKind,
	/**  Git's or ssh's prompt, shown as text (SEC-3). */
	text: string,
	workspace_name: string,
	repo_names: string[],
	job_label: string,
};

/**
 *  Git or ssh asks for something it cannot get silently, sent as event
 *  `askpass_prompt` (D10). Answered with `askpass_answer`.
 */
export type AskpassPromptEvent = AskpassPrompt;

/**  What the branch dialogs offer for one repo. */
export type BranchChoices = {
	/**
	 *  Local branches, remote branches with their remote, and tags, each
	 *  group sorted: start points to pick from.
	 */
	start_points: string[],
	/**  The default branch as git shortens it, such as `origin/main`. */
	default_branch: string | null,
	/**  Every remote branch: upstreams to pick from. */
	remote_branches: RemoteBranchRef[],
};

/**  A branch operation (section 6 "Branches"). */
export type BranchOp = 
/**  Checks out local branch `name`. */
{ kind: "checkout"; name: string } | 
/**
 *  Checks out a remote branch: the local branch of the same name when
 *  there is one, else a new one that tracks it.
 */
{ kind: "checkout_remote"; branch: RemoteBranchRef } | 
/**
 *  Checks out the commit `revision` names, a hash or a tag, with a
 *  detached `HEAD`.
 */
{ kind: "checkout_detached"; revision: string } | 
/**  Creates branch `name` at `start`, checked out when `switch`. */
{ kind: "create"; name: string; start: StartPoint; switch: boolean } | { kind: "rename"; name: string; new_name: string } | 
/**
 *  Deletes local branch `name`. `force` deletes it when not merged;
 *  `on_remote` also deletes the branch it tracks on its remote. Both
 *  are destructive (GRP-9).
 */
{ kind: "delete"; name: string; force: boolean; on_remote: boolean } | 
/**  Deletes a branch on its remote. Destructive (GRP-9). */
{ kind: "delete_remote"; branch: RemoteBranchRef } | 
/**  Makes branch `name` track `upstream`, or nothing when `None`. */
{ kind: "set_upstream"; name: string; upstream: RemoteBranchRef | null };

/**  A branch operation on one repo. */
export type BranchRequest = {
	repo_id: RepoId,
	op: BranchOp,
	/**  The user confirmed a destructive operation (GRP-9). */
	confirmed: boolean,
};

/**  What a request did. */
export type BranchStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  The operation is destructive (GRP-9): ask again with `confirmed`
 *  once the user agreed. `actions` says what cannot be undone.
 */
{ kind: "confirm"; repo: string; actions: string[] };

/**  What [`Jobs::cancel`] did. */
export type CancelResult = 
/**  It had not started and never will. */
"cancelled" | 
/**  Its git process is being killed. */
"killing" | 
/**  It runs to its end (GRP-10). */
"finishing" | 
/**  It has ended, or never existed. */
"ended";

/**  What to do with the files or the hunk. */
export type ChangeAction = 
/**  Unstaged to staged. */
"stage" | 
/**  Staged to unstaged. */
"unstage" | 
/**
 *  Unstaged changes undone in the working tree; untracked files and
 *  folders deleted. Destructive (GRP-9).
 */
"discard";

/**  A stage, unstage or discard request of the changes pane. */
export type ChangeRequest = {
	/**  The view whose files or diff the request names. */
	handle: number,
	action: ChangeAction,
	target: ChangeTarget,
	/**  The user confirmed the discard (GRP-9). */
	confirmed: boolean,
};

/**  What a request did. */
export type ChangeStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  A discard needs the user's confirmation (GRP-9): ask again with
 *  `confirmed` once the user agreed. Names for display.
 */
{ kind: "confirm"; repo: string; files: string[] } | 
/**
 *  The hunk's file changed since its diff was read; nothing ran, and
 *  the view should be read again.
 */
{ kind: "file_changed" };

/**  Which changes of a view. */
export type ChangeTarget = 
/**  Whole files, all of one list. */
{ kind: "files"; files: FileRef[] } | 
/**
 *  Hunk `hunk`, from 0, of the diff of `file` last read with
 *  `diff_get`.
 */
{ kind: "hunk"; file: FileRef; hunk: number };

/**  One entry of a changed-file list. It holds no content (ARCH-8). */
export type ChangedFile = {
	/**  The index in the list it came from. */
	id: number,
	/**  The path for display, decoded lossily; never sent back. */
	path: string,
	/**  The path before a rename, for display. */
	old_path: string | null,
	status: FileStatus,
	mode_change: ModeChange | null,
	/**
	 *  Line counts for text files when the list is short enough
	 *  ([`MAX_COUNTED_FILES`]).
	 */
	added: number | null,
	removed: number | null,
};

/**  What the changes pane lists. */
export type ChangesContent = { kind: "commit"; details: CommitDetails; 
/**  The parent the files are compared with. */
parent: number; files: ChangedFile[] } | { kind: "uncommitted"; staged: ChangedFile[]; 
/**  Untracked files included. */
unstaged: ChangedFile[]; 
/**  In neither list above, as in `git status`. */
unmerged: UnmergedFile[]; 
/**
 *  The last commit's message, which Amend starts from; `None` on a
 *  branch with no commit yet, where there is nothing to amend.
 */
last_message: CommitMessage | null; 
/**
 *  In conflict state (OPS-1): no commit box, as Continue makes the
 *  commit (M2-08).
 */
in_conflict: boolean };

/**
 *  The changes pane's view, remembered for every workspace (UI-14,
 *  UI-17). A key missing from the file takes its default (see [`decode`]).
 */
export type ChangesSettings = {
	diff_mode: DiffMode,
	file_list: FileListMode,
	ignore_whitespace: boolean,
	wrap_lines: boolean,
	context: Context,
};

/**  What to show. */
export type ChangesTarget = 
/**  A commit against one of its parents, 0 being the first (UI-16). */
{ kind: "commit"; hash: string; parent: number } | 
/**  The working copy (UI-15). */
{ kind: "uncommitted" };

/**  A view of the changes pane. */
export type ChangesView = {
	/**
	 *  Names this view for `diff_get`, `diff_image` and the conflict
	 *  editor's calls.
	 */
	handle: number,
	content: ChangesContent,
};

/**  Why a conflict is a choice and not text hunks (OPS-6). */
export type ChoiceKind = 
/**
 *  Binary content: a NUL in the first 8,000 bytes of a side, or the
 *  `binary`, `-diff` or `-merge` attribute.
 */
"binary" | "deleted_by_us" | "deleted_by_them" | 
/**  Neither side kept the file, as after a rename on each side. */
"both_deleted" | 
/**
 *  Both sides are files whose modes differ, and neither kept the
 *  base's: both added with different modes.
 */
"mode" | 
/**  A side is a submodule. */
"submodule" | 
/**  A file on one side and a symbolic link on the other. */
"type_change" | 
/**  A symbolic link on both sides. */
"symlink" | 
/**
 *  A side is not UTF-8. Shown as text it would be rewritten in another
 *  encoding.
 */
"not_utf8" | 
/**  A side has over [`MAX_CONFLICT_TEXT`] bytes (ARCH-8). */
"too_large" | 
/**
 *  A line starts with a run of marker characters too long to tell
 *  conflict markers from text.
 */
"marker_like";

/**  Resolve with one side (OPS-6). */
export type ChooseRequest = {
	handle: number,
	file: number,
	side: ConflictChoice,
};

/**
 *  A code theme for diffs and the conflict editor (UI-24). The UI holds
 *  their colors.
 */
export type CodeTheme = "github_light" | "github_dark" | "solarized_light" | "solarized_dark" | "one_dark" | "dracula" | "nord" | "monokai";

/**  A commit's header (UI-14). Text is decoded lossily (SEC-3). */
export type CommitDetails = {
	hash: string,
	author: Person,
	committer: Person,
	/**  The full message. */
	message: string,
	parents: string[],
};

/**  A commit-graph write job ended, sent as event `commit_graph_written`. */
export type CommitGraphWrittenEvent = {
	workspace_id: WorkspaceId,
	repo_id: RepoId,
	job_id: JobId,
	/**  Why the write failed; `None` when the file was written. */
	error: string | null,
	/**  What git printed on stderr, when git ran and failed. */
	git_stderr: string | null,
};

/**  A commit message as the commit box edits it. */
export type CommitMessage = {
	/**  The first line. */
	subject: string,
	/**  The rest; may be empty. */
	body: string,
};

/**  A commit or amend request of the changes pane. */
export type CommitRequest = {
	/**  The view of the uncommitted changes the commit is made from. */
	handle: number,
	message: CommitMessage,
	/**  Replace the last commit instead of adding one. */
	amend: boolean,
};

/**
 *  One commit of a history page. Text from the repo is decoded lossily
 *  (SEC-3).
 */
export type CommitRow = {
	hash: string,
	short_hash: string,
	subject: string,
	author_name: string,
	author_email: string,
	author_time: Time,
	commit_time: Time,
	parents: string[],
	refs: RefLabel[],
	/**
	 *  The graph cell; `None` on a filtered page, whose rows are not
	 *  contiguous.
	 */
	graph: GraphRow | null,
};

/**
 *  Why a config file is read-only, shown to the user as a banner. Paths are
 *  text for display only (PLAT-2).
 */
export type ConfigWarning = 
/**
 *  The file at `path` has schema `found`, newer than the `supported` one.
 *  What this build understands of it is used; it is not written.
 */
{ kind: "newer_schema"; path: string; found: number; supported: number } | 
/**
 *  The file at `path` could not be read or parsed, for `reason`. The
 *  defaults are used; the file is not written.
 */
{ kind: "unreadable"; path: string; reason: string } | 
/**  The platform has no config dir, so nothing can be saved. */
{ kind: "no_config_dir" };

/**  A conflicted file (OPS-3, OPS-8). */
export type Conflict = {
	/**  The path for display, decoded lossily (PLAT-2). */
	path: string,
	labels: ConflictLabels,
	content: ConflictContent,
	/**
	 *  The file on disk is not what git wrote for the conflict: it was
	 *  edited outside the app (OPS-8). Only for a text conflict.
	 */
	edited_outside: boolean,
	/**
	 *  The file's text when it was edited outside, is UTF-8 and has at
	 *  most [`MAX_CONFLICT_TEXT`] bytes: what the editor opens to keep the
	 *  file as it is (OPS-8).
	 */
	on_disk: string | null,
};

/**  A side of a conflict. */
export type ConflictChoice = "ours" | "theirs";

/**  A part of a conflicted text file (OPS-3, OPS-8). */
export type ConflictChunk = 
/**  Text both sides agree on, or that only one side changed. */
{ kind: "resolved"; text: string } | 
/**
 *  Lines the two sides changed differently, with the base they started
 *  from, in diff3 style. Each part ends with its line ending.
 */
{ kind: "hunk"; ours: string; base: string; theirs: string };

/**  What the editor shows of a conflicted file. */
export type ConflictContent = 
/**  The file merged in diff3 style, in order (OPS-8). */
{ kind: "text"; chunks: ConflictChunk[] } | 
/**  A choice between the two versions (OPS-6). */
{ kind: "choice"; reason: ChoiceKind; ours: SideHolds; theirs: SideHolds };

/**
 *  An operation in conflict state as the banner names it (OPS-2). Each part
 *  git does not record is `None`.
 */
export type ConflictDetails = {
	operation: Operation | null,
	/**
	 *  What is applied: the merged branch or commit, the branch being
	 *  rebased, the commit being cherry-picked or reverted; never a stash,
	 *  which git does not record. A commit reads `1a2b3c4 Subject`.
	 */
	applying: string | null,
	/**
	 *  Where: the current branch, or for a rebase the branch or commit it
	 *  rebases onto.
	 */
	onto: string | null,
	/**  A rebase or `git am`: the commit or patch that stopped. */
	step: Step | null,
	/**  Paths with conflict stages in the index; Continue waits for 0. */
	unmerged_paths: number,
};

/**
 *  What "ours" and "theirs" of a conflicted file are (OPS-4): the real
 *  branch or commit each side comes from, as the conflict state names it
 *  (OPS-1). A commit with a branch at it reads as the branch, else as
 *  `1a2b3c4 Subject`.
 */
export type ConflictLabels = {
	ours: string,
	theirs: string,
};

/**  What `conflict_get` found. */
export type ConflictRead = { kind: "conflict"; conflict: Conflict } | 
/**  The file is no longer in conflict; read the lists again. */
{ kind: "already_resolved" };

/**  What a resolution request did. */
export type ConflictStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  The file is no longer in conflict; nothing ran. Read the lists
 *  again.
 */
{ kind: "already_resolved" } | 
/**
 *  Mark resolved was refused: line `line`, from 1, of the text is a
 *  conflict marker line (OPS-5). Ask again with the override when the
 *  file legitimately has such lines.
 */
{ kind: "markers_remain"; line: number };

/**  How much unchanged text surrounds each change (UI-17). */
export type Context = "three" | "ten" | 
/**  One hunk spanning the file, and both sides' full text. */
"whole_file";

/**  How the diff shows a text file (UI-17). */
export type DiffMode = "inline" | "side_by_side";

/**  The options of a file diff (UI-17, UI-18), as the UI sends them. */
export type DiffRequest = {
	ignore_whitespace: boolean,
	context: Context,
	/**  Return the hunks of a diff over the line limit (UI-18). */
	load_anyway: boolean,
	/**  Return both whole files with the hunks (side-by-side mode). */
	full_text: boolean,
};

/**  Where the changes pane sits (UI-19). */
export type Dock = "right" | "bottom";

/**
 *  One line segment within half a row. A line keeps its color index from
 *  the row where it starts to the row where it ends.
 */
export type Edge = {
	from: number,
	to: number,
	color: number,
};

/**  The diff of one file. */
export type FileDiff = {
	kind: "text",
} & TextDiff | 
/**  Sizes in bytes; `None` for a side that does not exist. */
({ kind: "binary"; 
/**  Typed for specta like [`Image::size`]. */
old_size: number | null; new_size: number | null }) & { added?: never; new?: never; old?: never; removed?: never } | ({ kind: "image"; old: Image | null; new: Image | null }) & { added?: never; new_size?: never; old_size?: never; removed?: never } | 
/**  Over [`MAX_DIFF_LINES`] changed lines: the counts only. */
({ kind: "too_large"; added: number; removed: number }) & { new?: never; new_size?: never; old?: never; old_size?: never } | 
/**  An untracked folder git lists as one entry; its files are not read. */
({ kind: "directory" }) & { added?: never; new?: never; new_size?: never; old?: never; old_size?: never; removed?: never } | 
/**  The submodule's commit on each side. */
({ kind: "submodule"; old: string | null; new: string | null }) & { added?: never; new_size?: never; old_size?: never; removed?: never };

/**  The list a file of a view belongs to. */
export type FileList = "commit" | "staged" | "unstaged";

/**  How the changes pane lists files (UI-14). */
export type FileListMode = "flat" | "tree";

/**  A file of a view: its list and its id in that list. */
export type FileRef = {
	list: FileList,
	id: number,
};

/**  How a file changed. */
export type FileStatus = "added" | "modified" | "deleted" | "renamed" | 
/**  File, symbolic link and submodule turned into one another. */
"type_changed" | 
/**
 *  In the working tree but not in the index. A folder git lists as one
 *  entry has a path ending in `/`.
 */
"untracked";

/**
 *  Whether a usable git was found, as shown to the user. Paths and versions
 *  are converted to text here, for display only (PLAT-2).
 */
export type GitStatus = 
/**  Detection has not finished yet. */
{ kind: "checking" } | 
/**  git at `path` is new enough. */
{ kind: "usable"; path: string; version: string } | 
/**  No git at any of the `searched` paths. */
{ kind: "not_found"; searched: string[] } | 
/**  git at `path` is version `found`; `required` or newer is needed. */
{ kind: "too_old"; path: string; found: string; required: string } | 
/**
 *  git at `path` did not report a version; `output` is what it printed or
 *  why it did not run.
 */
{ kind: "unparseable"; path: string; output: string };

/**
 *  The result of git detection, sent as event `git_status` whenever it
 *  changes: `checking` when detection starts, then the result (PLAT-3).
 */
export type GitStatusEvent = GitStatus;

/**  The graph cell of one history row. */
export type GraphRow = {
	/**  The lane the commit sits on. */
	lane: number,
	/**  The color index of the commit's line. */
	color: number,
	/**
	 *  Lines in the upper half of the row, from the top edge (`from`) to the
	 *  middle (`to`): lines ending at the commit, and lines passing it.
	 */
	up: Edge[],
	/**
	 *  Lines in the lower half, from the middle (`from`) to the bottom edge
	 *  (`to`): lines leaving the commit for its parents, and lines passing it.
	 */
	down: Edge[],
};

/**  Where `HEAD` is. */
export type Head = 
/**  On a branch; `hash` is `None` while it has no commit yet. */
{ kind: "branch"; name: string; hash: string | null } | { kind: "detached"; hash: string };

/**
 *  What the history pane shows for a single-repo selection (section 8
 *  "History pane"). Names are short, as the tree shows them.
 */
export type HistoryTarget = 
/**  Every local and remote branch. */
{ kind: "repo" } | 
/**  A local branch, such as `main`. */
{ kind: "branch"; name: string } | 
/**  A remote branch with its remote, such as `origin/main`. */
{ kind: "remote_branch"; name: string } | { kind: "tag"; name: string } | 
/**  `stash@{index}`, shown as one row. */
{ kind: "stash"; index: number };

/**  A page of the history the pane shows. */
export type HistoryView = {
	/**  Names this walk for `history_more`. */
	handle: number,
	rows: CommitRow[],
	/**  No page follows. */
	done: boolean,
	/**
	 *  Offer to write a commit-graph file for the repo (PERF-2). Only a
	 *  first page sets it.
	 */
	offer_commit_graph: boolean,
};

/**
 *  A run of changes with its context. Starts and counts are as in a
 *  unified diff header: `@@ -old_start,old_lines +new_start,new_lines @@`.
 */
export type Hunk = {
	old_start: number,
	old_lines: number,
	new_start: number,
	new_lines: number,
	lines: Line[],
};

/**  One side of an image diff. */
export type Image = {
	format: ImageFormat,
	/**
	 *  In bytes. specta refuses `u64` because it would be a `bigint`; as a
	 *  JavaScript number, any file size is exact.
	 */
	size: number,
};

/**  An image format shown as a picture (UI-18). */
export type ImageFormat = "png" | "jpeg" | "gif" | "webp" | "bmp";

/**  A side of an image diff. */
export type ImageSide = "old" | "new";

/**
 *  An integrate operation (section 6 "Integrate"), or what to do with one
 *  stopped in conflict state (OPS-2).
 */
export type IntegrateOp = 
/**  Merges `revision`, a ref or a hash, into the current branch. */
{ kind: "merge"; revision: string; fast_forward: MergeFastForward } | 
/**  Rebases the current branch onto `onto`, a ref or a hash. */
{ kind: "rebase"; onto: string } | 
/**  Applies `commits`, oldest first whatever their order here. */
{ kind: "cherry_pick"; commits: string[] } | 
/**
 *  Reverts `commit`. A merge commit needs `mainline`, the parent whose
 *  side is kept, counted from 1; without it the core asks.
 */
{ kind: "revert"; commit: string; mainline: number | null } | 
/**  Aborts the operation the repo is in. */
{ kind: "abort" } | 
/**  Continues the operation the repo is in once no path is unmerged. */
{ kind: "continue" };

/**  An integrate operation on one repo. */
export type IntegrateRequest = {
	repo_id: RepoId,
	op: IntegrateOp,
	/**  The user confirmed an operation that cannot be undone. */
	confirmed: boolean,
};

/**  What a request did. */
export type IntegrateStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  A revert of a merge commit: ask again with the parent whose side is
 *  kept. `commit` is its full hash, `parents` each parent as
 *  `1a2b3c4 Subject`, the first being mainline 1.
 */
{ kind: "choose_mainline"; commit: string; parents: string[] } | 
/**
 *  The operation cannot be undone: ask again with `confirmed` once the
 *  user agreed. `actions` says what is lost.
 */
{ kind: "confirm"; repo: string; actions: string[] };

/**  The error every command returns. */
export type IpcError = {
	code: IpcErrorCode,
	message: string,
	/**  What git printed on stderr, when the error came from a git command. */
	git_stderr: string | null,
};

/**  What kind of failure an [`IpcError`] reports. */
export type IpcErrorCode = 
/**  A bug or an environment problem the user cannot fix from the UI. */
"internal" | 
/**  The settings are read-only (DATA-1); `settings_get` says why. */
"settings_read_only" | 
/**  The workspace is read-only (DATA-1); its view says why. */
"workspace_read_only" | 
/**  No open workspace has the id, or the workspace has no such repo. */
"not_found" | 
/**  No usable git was found (PLAT-3); `git_status` says why. */
"git_unavailable";

/**
 *  A job ended, sent as event `job_ended` with its outcome and git's
 *  output, after its repos' fresh summaries.
 */
export type JobEndedEvent = JobView;

/**  Identifies a job, unique while the app runs. */
export type JobId = number;

/**
 *  A job was queued, began to run, or made progress, sent as event
 *  `job_progress` (ARCH-7, UI-21).
 */
export type JobProgressEvent = JobView;

/**  Where a job is. */
export type JobState = 
/**  Waiting for its repos or for a worker. */
"queued" | "running" | "ended";

/**  A job as the status bar and the job list show it (UI-21). */
export type JobView = {
	job_id: JobId,
	workspace_id: WorkspaceId,
	/**  The workspace's name when the job was started. */
	workspace_name: string,
	label: string,
	repos: RepoId[],
	/**  The names of `repos`, in their order, when the job was started. */
	repo_names: string[],
	state: JobState,
	/**
	 *  How far it has come: `done` of `total` steps. A `total` of 0 means
	 *  the number of steps is not known yet.
	 */
	done: number,
	total: number,
	/**
	 *  The phase `done` and `total` count, as git names it, such as
	 *  `Receiving objects`; `None` when the job reports no phases.
	 */
	step: string | null,
	/**  When it began to run, in milliseconds since the Unix epoch. */
	started_at: number | null,
	/**  How long it ran, in milliseconds; set when it ended. */
	duration_ms: number | null,
	/**  Set when the job has ended. */
	outcome: Outcome | null,
	/**
	 *  What git printed, stdout then stderr, progress lines folded to their
	 *  last state; at most [`MAX_OUTPUT`] bytes, the end kept.
	 */
	output: string,
	/**  Why a failed or skipped job did not succeed. */
	message: string | null,
};

/**  One line of a hunk, without its line terminator. */
export type Line = {
	kind: LineKind,
	/**  1-based line number on the old side; `None` for an added line. */
	old_line: number | null,
	/**  1-based line number on the new side; `None` for a removed line. */
	new_line: number | null,
	text: string,
};

/**  What a diff line is. */
export type LineKind = "context" | "added" | "removed";

/**  Whether a merge may fast-forward (section 5 "Merge X into current"). */
export type MergeFastForward = 
/**
 *  As `merge.ff` says; by default a fast-forward when possible, else a
 *  merge commit.
 */
"config" | 
/**  Fast-forward, or fail. */
"ff_only" | 
/**  Always a merge commit. */
"no_ff";

/**  Both modes, as git writes them (`100644`), when they differ. */
export type ModeChange = {
	old: string,
	new: string,
};

/**
 *  An operation that stopped part way and waits to be continued or
 *  aborted.
 */
export type Operation = 
/**  `MERGE_HEAD`. */
"merge" | 
/**  `rebase-merge`, or `rebase-apply` from `git rebase`. */
"rebase" | 
/**  `rebase-apply` from `git am`. */
"apply_mailbox" | 
/**  `CHERRY_PICK_HEAD`. */
"cherry_pick" | 
/**  `REVERT_HEAD`. */
"revert" | 
/**
 *  Unmerged paths and none of the files above: a stash applied or
 *  popped with conflicts, as git keeps no state file for it. It ends
 *  when the last path is staged.
 */
"stash_apply";

/**
 *  How a job ended (GRP-7). *Conflict* is not a failure: git left the repo
 *  in conflict state (OPS-1).
 */
export type Outcome = { kind: "succeeded" } | { kind: "nothing_to_do" } | { kind: "skipped"; reason: SkipReason } | { kind: "failed" } | { kind: "conflict" };

/**
 *  The workspace's pane layout (section 10, UI-19): where the changes pane
 *  is docked and the pane sizes in CSS pixels. A field missing from the
 *  file is `None`, and the UI uses its default; TOML leaves `None` out.
 */
export type PaneLayout = {
	dock: Dock | null,
	/**  The tree pane's width. */
	tree: number | null,
	/**  The history pane's width while the changes pane is docked right. */
	history: number | null,
	/**  The changes pane's height while it is docked at the bottom. */
	changes: number | null,
};

/**
 *  One step of the start and when it happened, in milliseconds since the
 *  Unix epoch.
 */
export type PerfMark = {
	name: string,
	unix_ms: number | null,
};

/**  One measurement the UI took, in milliseconds. */
export type PerfSample = {
	scenario: string,
	ms: number | null,
};

/**  What the UI measured in one run of the app. */
export type PerfTrace = {
	/**
	 *  When the tree first showed the cached repos, in milliseconds
	 *  since the Unix epoch; `None` when it never did.
	 */
	tree_visible_unix_ms: number | null,
	samples: PerfSample[],
	/**
	 *  Steps of the start the page saw, as `performance.mark` names
	 *  them, in milliseconds since the Unix epoch (M1-15).
	 */
	marks: PerfMark[],
};

/**  A commit author or committer. */
export type Person = {
	name: string,
	email: string,
	time: Time,
};

/**  What git asks for. */
export type PromptKind = 
/**  A name or other text, shown as it is typed. */
"text" | 
/**  A password or passphrase, masked. */
"secret" | 
/**  An SSH host key question, answered `yes` or `no`. */
"yes_no";

/**
 *  Whether a fetch removes remote-tracking branches whose branch is gone
 *  from the remote.
 */
export type Prune = 
/**  As `fetch.prune` and `remote.<name>.prune` say. */
"config" | "prune" | "no_prune";

/**  How a pull brings in its upstream (section 5 "Pull"). */
export type PullStrategy = 
/**
 *  As `branch.<name>.rebase`, `pull.rebase` and `pull.ff` say; with
 *  `pull.rebase` and `pull.ff` unset, fast-forward only.
 */
"config" | "ff_only" | 
/**  Fast-forward when possible, else a merge commit. */
"merge" | "rebase";

/**  What the push options offer for one repo. */
export type PushChoices = {
	/**  The current branch; `None` when `HEAD` is detached. */
	branch: string | null,
	/**
	 *  Where the branch pushes to, such as `origin/main`; `None` without an
	 *  upstream.
	 */
	upstream: string | null,
	/**  Every remote, sorted. */
	remotes: string[],
	/**
	 *  Where a push without an upstream goes when no remote is picked;
	 *  `None` when the user must pick one.
	 */
	remote: string | null,
};

/**  The kind of a ref label on a history row. */
export type RefKind = 
/**  `HEAD`, shown only when it is detached. */
"head" | 
/**  The local branch `HEAD` points to. */
"current_branch" | "local_branch" | "remote_branch" | "tag";

/**  A ref pointing at a commit, by its short name. */
export type RefLabel = {
	kind: RefKind,
	name: string,
};

/**
 *  A folder that was not added, and why. Git's own refusals carry git's
 *  message (SEC-6). The path is text for display only (PLAT-2).
 */
export type Refusal = {
	path: string,
	reason: string,
};

/**  A branch of a remote, such as `feature/x` of `origin`. */
export type RemoteBranchRef = {
	remote: string,
	/**  Without the remote. */
	branch: string,
};

/**  Identifies a repo inside its workspace: `r1`, `r2` and so on. */
export type RepoId = string;

/**  A repo of a workspace. */
export type RepoRef = {
	workspace_id: WorkspaceId,
	repo_id: RepoId,
};

/**
 *  A repo's loaded refs were dropped because its summary was read again,
 *  sent as event `repo_refs_changed`; `refs_get` reads them anew.
 */
export type RepoRefsChangedEvent = RepoRef;

/**  Whether a repo is in conflict state (OPS-1). */
export type RepoState = {
	/**  The operation in progress, if any. */
	operation: Operation | null,
	/**  How many paths have conflict stages in the index. */
	unmerged_paths: number,
};

/**  What a repo row shows (UI-3) and the cache keeps (PERF-3). */
export type RepoSummary = {
	head: Head,
	/**  `None` when the branch has no upstream or `HEAD` is detached. */
	upstream: Upstream | null,
	/**  Anything staged, unstaged, untracked or unmerged. */
	dirty: boolean,
	/**
	 *  How many distinct paths are staged, unstaged, untracked or unmerged
	 *  (UI-10); 0 exactly when not `dirty`.
	 */
	changes: number,
	state: RepoState,
};

/**
 *  One repo's fresh summary, sent as event `repo_summary` each time a repo
 *  has been read (PERF-3).
 */
export type RepoSummaryEvent = SummaryView;

/**  A repo as the UI sees it. The path is text for display only (PLAT-2). */
export type RepoView = {
	id: RepoId,
	/**  The repo's folder name. */
	name: string,
	path: string,
	/**  The URL of `origin`, or of the only remote, when it was added. */
	remote: string | null,
};

/**  Mark resolved with the editor's text (OPS-5). */
export type ResolveRequest = {
	/**  The changes view whose unmerged list `file` is from. */
	handle: number,
	file: number,
	text: string,
	/**  Mark resolved although the text has conflict marker lines. */
	override_markers: boolean,
};

/**
 *  Every setting. A key missing from the file takes its default (see
 *  [`decode`]).
 */
export type Settings = {
	theme: Theme,
	changes: ChangesSettings,
} & Appearance;

/**  The settings as the UI sees them. */
export type SettingsView = {
	settings: Settings,
	/**  Changes are refused; `warning` says why. */
	read_only: boolean,
	warning: ConfigWarning | null,
};

/**  What a side of a choice conflict holds (OPS-6). */
export type SideHolds = { kind: "deleted" } | 
/**  Sizes in bytes, typed for specta like [`crate::Image::size`]. */
{ kind: "file"; size: number; executable: boolean } | { kind: "symlink"; size: number } | 
/**  The submodule's commit, a full hash. */
{ kind: "submodule"; commit: string };

/**  Why a job was skipped. */
export type SkipReason = 
/**  Cancelled before it started, or killed while it ran (GRP-10). */
"cancelled";

/**  Where a new branch starts. */
export type StartPoint = 
/**  The commit checked out now. */
{ kind: "head" } | 
/**  The default branch (glossary). */
{ kind: "default_branch" } | 
/**  A ref or a commit hash. */
{ kind: "revision"; revision: string };

/**  A stash operation (section 6 "Stash"). */
export type StashOp = 
/**
 *  Stashes the working copy's changes, with `message` unless it is
 *  blank, and its untracked files too when `include_untracked`.
 */
{ kind: "push"; message: string | null; include_untracked: boolean } | 
/**  Applies the entry to the working copy and keeps it. */
{ kind: "apply"; stash: StashRef } | 
/**
 *  Applies the entry and drops it; git keeps it when the apply
 *  conflicts.
 */
{ kind: "pop"; stash: StashRef } | 
/**  Drops the entry. Cannot be undone from the app. */
{ kind: "drop"; stash: StashRef };

/**  A stash entry as the tree showed it: `stash@{index}` with this commit. */
export type StashRef = {
	index: number,
	/**  The stash commit's full hash. */
	hash: string,
};

/**  A stash operation on one repo. */
export type StashRequest = {
	repo_id: RepoId,
	op: StashOp,
	/**  The user confirmed an operation that cannot be undone. */
	confirmed: boolean,
};

/**  What a request did. */
export type StashStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  The operation cannot be undone: ask again with `confirmed` once the
 *  user agreed. `actions` says what is lost.
 */
{ kind: "confirm"; repo: string; actions: string[] };

/**  Which step of a series stopped. */
export type Step = {
	/**  Counted from 1. */
	current: number,
	total: number,
};

/**  A repo's summary as the UI sees it. */
export type SummaryView = {
	workspace_id: WorkspaceId,
	repo_id: RepoId,
	/**
	 *  The last summary read, in this run or an earlier one; `None` when
	 *  the repo has never been read.
	 */
	summary: RepoSummary | null,
	/**
	 *  `summary` was not read in this run: it comes from the cache, or the
	 *  repo could not be read again (PERF-3).
	 */
	stale: boolean,
	/**  The repo's folder does not exist (UI-3). */
	missing: boolean,
	/**
	 *  Why the last read failed; git's own message when git refused the
	 *  repo (SEC-6).
	 */
	error: string | null,
	/**  A read of the repo is waiting or running (UI-3). */
	refreshing: boolean,
	/**  `summary` says the repo is in conflict state (OPS-1, UI-3). */
	conflict: boolean,
	/**
	 *  Goes up each time the repo's refs or `HEAD` are seen to have changed
	 *  in this run; the history reads the repo again when it does (OPS-7).
	 */
	refs_version: number,
	/**
	 *  A write job waits or runs on the repo, so other writes are disabled
	 *  (GRP-8) and the row shows the spinner (UI-3).
	 */
	busy: boolean,
};

/**  A sync operation (section 6 "Sync"). */
export type SyncOp = 
/**  Fetches every remote. */
{ kind: "fetch"; prune: Prune } | 
/**  Updates the current branch from its upstream. */
{ kind: "pull"; strategy: PullStrategy } | 
/**
 *  Pushes the current branch to its upstream. A branch without one goes
 *  to `remote`, else to `origin`, else to the only remote, and
 *  `set_upstream` makes that its upstream. `force_with_lease` replaces
 *  the remote branch when the push is not a fast-forward; destructive
 *  (GRP-9).
 */
{ kind: "push"; set_upstream: boolean; remote: string | null; force_with_lease: boolean };

/**  A sync operation on one repo. */
export type SyncRequest = {
	repo_id: RepoId,
	op: SyncOp,
	/**  The user confirmed a destructive operation (GRP-9). */
	confirmed: boolean,
};

/**  What a request did. */
export type SyncStart = 
/**  The job runs; its end re-reads the repo (OPS-7). */
{ kind: "started"; job_id: JobId } | 
/**
 *  The operation is destructive (GRP-9): ask again with `confirmed`
 *  once the user agreed. `actions` says what cannot be undone.
 */
{ kind: "confirm"; repo: string; actions: string[] } | 
/**
 *  A push of a branch without an upstream, in a repo with several
 *  remotes and no `origin`: ask again with one of `remotes`.
 */
{ kind: "choose_remote"; remotes: string[] };

/**  The diff of a text file. */
export type TextDiff = {
	added: number,
	removed: number,
	hunks: Hunk[],
	/**
	 *  Both sides in full, only when asked for or with
	 *  [`Context::WholeFile`] (side-by-side mode needs them); empty for a
	 *  side that does not exist.
	 */
	old_text: string | null,
	new_text: string | null,
	/**  The side's last line has no line terminator. */
	old_missing_newline: boolean,
	new_missing_newline: boolean,
};

/**  The app theme (UI-23). */
export type Theme = 
/**  Follow the OS light or dark mode, live. */
"system" | "light" | "dark";

/**  A point in time as git records it. */
export type Time = {
	/**
	 *  Seconds since the Unix epoch. A JavaScript number holds it exactly;
	 *  specta refuses `i64` because it would be a `bigint`.
	 */
	seconds: number,
	/**  The recorded time zone, in seconds east of UTC. */
	offset: number,
};

/**  What a node stands for. */
export type TreeItem = { kind: "ungrouped" } | { kind: "repo"; repo_id: RepoId } | { kind: "local"; repo_id: RepoId } | { kind: "remotes"; repo_id: RepoId } | { kind: "tags"; repo_id: RepoId } | { kind: "stashes"; repo_id: RepoId } | { kind: "remote"; repo_id: RepoId; remote: string } | 
/**  One `/`-separated part of branch names. */
{ kind: "folder"; repo_id: RepoId } | { kind: "branch"; repo_id: RepoId; 
/**  The full short name, for example `feature/x`. */
name: string; 
/**  `HEAD` points to it. */
current: boolean; 
/**  The upstream, for example `origin/main`. */
upstream: string | null; 
/**  The upstream is configured but its ref does not exist. */
gone: boolean; 
/**
 *  Commits ahead of and behind the upstream; `None` when not
 *  counted or there is nothing to count against.
 */
ahead: number | null; behind: number | null } | { kind: "remote_branch"; repo_id: RepoId; 
/**  With the remote, for example `origin/feature/x`. */
name: string; 
/**  The remote, which may contain `/` itself, for example `origin`. */
remote: string; 
/**  Without the remote, for example `feature/x`. */
branch: string } | { kind: "tag"; repo_id: RepoId; name: string; annotated: boolean } | { kind: "stash"; repo_id: RepoId; 
/**  `n` in `stash@{n}`. */
index: number; 
/**  The stash commit's full hash: what a stash operation names it by. */
hash: string; message: string; 
/**
 *  Seconds since the Unix epoch. A plain `number` in TypeScript,
 *  which `i64` is not by default.
 */
seconds: number };

/**
 *  One node of the tree. Ids are unique within a workspace and stable
 *  across reads, so the UI can keep expanded and selected nodes by id.
 */
export type TreeNode = {
	id: string,
	/**  What the row shows: a repo name, a ref name or one folder of one. */
	label: string,
	item: TreeItem,
	/**
	 *  `None` while not loaded: a repo's ref nodes before [`tree_refs`].
	 *  Leaves have `Some` and no children.
	 */
	children: TreeNode[] | null,
};

/**  A path with conflict stages in the index. */
export type UnmergedFile = {
	/**  The index in [`WorkingCopy::unmerged`]. */
	id: number,
	/**  The path for display, decoded lossily; never sent back (PLAT-2). */
	path: string,
	conflict: UnmergedKind,
};

/**  How the two sides of a merge left a path, as `git status` names it. */
export type UnmergedKind = "both_deleted" | "added_by_us" | "deleted_by_them" | "added_by_them" | "deleted_by_us" | "both_added" | "both_modified";

/**  The branch the current branch tracks. */
export type Upstream = {
	/**  As git shortens it, for example `origin/main`. */
	name: string,
	/**  Commits on the branch and not on the upstream. */
	ahead: number,
	/**  Commits on the upstream and not on the branch. */
	behind: number,
	/**
	 *  The upstream is configured but its ref does not exist, for example
	 *  after the remote branch was deleted and pruned. Counts are then 0.
	 */
	gone: boolean,
};

/**
 *  Watching a workspace failed, at least in part. Changes made outside the
 *  app then show when the window regains focus (OPS-7).
 */
export type WatchWarning = {
	workspace_id: WorkspaceId,
	message: string,
};

/**
 *  Watching a workspace's files failed, sent once as event `watch_warning`;
 *  changes made outside the app then show when the window regains focus.
 */
export type WatchWarningEvent = WatchWarning;

/**
 *  What an add job did, sent as event `workspace_add_report` when it ends,
 *  after its `workspace_changed`.
 */
export type WorkspaceAddReportEvent = AddReport;

/**
 *  A workspace's fresh state, sent as event `workspace_changed` after it
 *  changes (ARCH-6).
 */
export type WorkspaceChangedEvent = WorkspaceView;

/**  Identifies a workspace. All session state is keyed by it (ARCH-9). */
export type WorkspaceId = string;

/**  A workspace as the UI sees it. */
export type WorkspaceView = {
	id: WorkspaceId,
	name: string,
	/**  In the order they were added. */
	repos: RepoView[],
	layout: PaneLayout,
	/**  Changes are refused; `warning` says why. */
	read_only: boolean,
	warning: ConfigWarning | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

